export type SKey = keyof typeof S
const IDX = { en: 0, ar: 1, ku: 2 } as const

/** the dashboard's `t`: s('nItems', { n: 3 }) */
export function useS() {
  const { lang } = useLang()
  return useCallback((key: SKey, vars?: Record<string, string | number>) => {
    let out: string = S[key][IDX[lang]]
    if (vars) for (const [k, v] of Object.entries(vars)) out = out.replace(`{${k}}`, String(v))
    return out
  }, [lang])
}

/** a dashboard string in a given language, outside the dashboard's own (a driver's message) */
export function sIn(lang: Lang, key: SKey, vars?: Record<string, string | number>) {
  let out: string = S[key][IDX[lang]]
  if (vars) for (const [k, v] of Object.entries(vars)) out = out.replace(`{${k}}`, String(v))
  return out
}
